import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import base64

app = Flask(__name__)
DATABASE = '/tmp/app.db'
ALLOWED_ROLES = os.environ.get('ALLOWED_ROLES', 'admin,analyst,viewer')
MAX_RESULTS = int(os.environ.get('MAX_RESULTS', '100'))
ENABLE_AUDIT = os.environ.get('ENABLE_AUDIT', '0') == '1'
DB_MODE = os.environ.get('DB_MODE', 'wal')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
        db.execute(f'PRAGMA journal_mode={DB_MODE}')
        db.execute('PRAGMA foreign_keys=ON')
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, username TEXT, email TEXT, role TEXT, password_hash TEXT)')
    db.execute('CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id INTEGER, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)')
    db.execute('CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT, action TEXT, details TEXT, ts TIMESTAMP DEFAULT CURRENT_TIMESTAMP)')
    db.execute("INSERT OR IGNORE INTO users VALUES (1, 'admin', 'admin@corp.local', 'admin', 'redacted')")
    db.execute("INSERT OR IGNORE INTO users VALUES (2, 'svc_reporting', 'svc@corp.local', 'analyst', 'redacted')")
    db.commit()
    db.close()

@app.before_request
def check_session():
    if request.path == '/health':
        return None
    session_id = request.headers.get('X-Session-ID')
    if not session_id:
        return jsonify({'error': 'missing session'}), 401
    db = get_db()
    row = db.execute('SELECT user_id FROM sessions WHERE id = ?', (session_id,)).fetchone()
    if not row:
        return jsonify({'error': 'invalid session'}), 403
    g.user_id = row['user_id']

@app.route('/health')
def health():
    return 'ok'

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports flexible querying."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')
    comparator = request.args.get('cmp', 'eq')

    # Field whitelist check
    allowed_fields = ['username', 'email', 'role', 'id']
    if field not in allowed_fields:
        return jsonify({'error': 'invalid field'}), 400

    # Build comparator - NOTE: comparator is NOT in whitelist
    cmp_map = {'eq': '=', 'like': 'LIKE', 'neq': '!='}
    sql_cmp = cmp_map.get(comparator, '=')

    # Vulnerable: value is interpolated directly
    query = f"SELECT id, username, email, role FROM users WHERE {field} {sql_cmp} '{value}' LIMIT {MAX_RESULTS}"

    if ENABLE_AUDIT:
        db = get_db()
        db.execute('INSERT INTO audit_log (action, details) VALUES (?, ?)', ('search', query))
        db.commit()

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>/notes', methods=['PUT'])
def update_notes(user_id):
    """Update user notes field - admin only."""
    data = request.get_json(force=True)
    note = data.get('note', '')
    # Vulnerable: note value directly interpolated
    query = f"UPDATE users SET email = '{note}' WHERE id = {user_id}"
    try:
        db = get_db()
        db.execute(query)
        db.commit()
        return jsonify({'status': 'updated'})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
